package com.mygo.music;

import android.app.*;
import android.content.*;
import android.content.res.Configuration;
import android.graphics.Bitmap;
import android.os.SystemClock;
import android.webkit.WebView;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

/** Original provider login, large QR pixels, visible source account access and native vector controls. */
final class LoginUiChecks {
    final Instrumentation test;final Context context;final CompletionChecks helper;
    LoginUiChecks(Instrumentation test){this.test=test;context=test.getTargetContext();helper=new CompletionChecks(test);}
    static void check(boolean ok,String text){if(!ok)throw new AssertionError(text);}
    String asset(String name)throws Exception{try(InputStream in=test.getContext().getAssets().open("provider-fixes/"+name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);return out.toString("UTF-8");}}
    String bili()throws Exception{File root=new File(context.getCacheDir(),"bilibili-login-adapter");root.mkdirs();File file=new File(root,"index.js");String original=asset("bilibili-original.js");try(FileOutputStream out=new FileOutputStream(new File(root,"plugin.json"))){out.write("{\"id\":\"bilibili\",\"main\":\"index.js\"}".getBytes("UTF-8"));}try(FileOutputStream out=new FileOutputStream(file)){out.write(original.getBytes("UTF-8"));}String source;try(InputStream in=new PluginAdapters(root).open(file);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);source=out.toString("UTF-8");}check(!source.equals(original)&&PluginIdentity.read(file).equals(original),"Bilibili QR adapter missing or changed installation");try(FileOutputStream out=new FileOutputStream(file)){out.write((original+"\n").getBytes("UTF-8"));}try(InputStream in=new PluginAdapters(root).open(file)){check(new String(in.readAllBytes(),"UTF-8").equals(original+"\n"),"unknown Bilibili source changed");}PluginArchive.delete(root);return source;}
    PluginRuntime runtime(PluginManager manager,String id)throws Exception{return (PluginRuntime)((Map<?,?>)FullPortChecks.field(manager,"runtimes")).get(id);}
    void screenshot(String name)throws Exception{Bitmap image=test.getUiAutomation().takeScreenshot();if(image!=null)try{File root=new File(context.getExternalFilesDir(null),"qa/login-repair");root.mkdirs();try(FileOutputStream out=new FileOutputStream(new File(root,name+".png"))){image.compress(Bitmap.CompressFormat.PNG,100,out);}}finally{image.recycle();}}
    int icons(android.view.View view){int count=view instanceof TextView&&((TextView)view).getCompoundDrawables()[0] instanceof AppIcons?1:0;if(view instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)view;for(int i=0;i<group.getChildCount();i++)count+=icons(group.getChildAt(i));}return count;}
    void run()throws Exception{provider(false);provider(true);System.out.println("MYGO_LOGIN_UI_OK: original Bilibili native QR/poll/candidate validation and Ximalaya website account validation, large native/browser QR, fullscreen QR pixels, cancel/failure preserve source account, persistent account entry and local vector icons");}
    void provider(boolean ximalaya)throws Exception{
        String id=ximalaya?"ximalaya-login-ui":"bilibili-login-ui";helper.cleanup(id);MainActivity activity=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));PluginManager manager=new PluginManager(activity);String[] raw={""};boolean[] success={false};
        try(Server server=new Server()){
            String prefix="const __fetch=globalThis.fetch;globalThis.fetch=(url,init)=>__fetch(String(url).replace(/^https:\\/\\/(api|passport)\\.bilibili\\.com/, '"+server.base()+"').replace('https://www.ximalaya.com','"+server.base()+"'),init);const __web=host.webSignIn;host.webSignIn=options=>__web({...options,url:'"+server.base()+"/login',cookiesOf:'"+server.base()+"/'});\n";
            helper.install(manager,id,"stream",new JSONArray(),prefix+(ximalaya?asset("ximalaya-original.js"):bili()));File manifest=new File(context.getFilesDir(),"plugins/"+id+"/plugin.json");JSONObject settings=new JSONObject(PluginIdentity.read(manifest)).put("permissions",new JSONObject().put("network",new JSONArray().put("127.0.0.1")));try(FileOutputStream out=new FileOutputStream(manifest)){out.write(settings.toString().getBytes("UTF-8"));}context.getSharedPreferences("library",0).edit().putBoolean("plugin_network_"+id,true).commit();
            helper.await(()->{Button account=(Button)FullPortChecks.field(activity,"landscapeAccount");return account!=null&&account.getWidth()>0&&account.getContentDescription().toString().contains("扫码登录")&&icons(activity.getWindow().getDecorView())>=8;},"visible account entry or local vector controls missing");
            CountDownLatch finished=new CountDownLatch(1);manager.export(id,"signIn",new JSONObject(),(ok,value)->{success[0]=ok;raw[0]=value;finished.countDown();});PluginRuntime[] login={null};helper.await(()->{login[0]=runtime(manager,id);return login[0]!=null&&FullPortChecks.field(login[0],ximalaya?"browserView":"loginBitmap")!=null;},"provider login QR did not appear");
            if(ximalaya){helper.await(()->((WebView)FullPortChecks.field(login[0],"browserView")).getProgress()==100&&activity.getResources().getConfiguration().orientation==Configuration.ORIENTATION_PORTRAIT,"Ximalaya portrait website missing");helper.await(()->((WebView)FullPortChecks.field(login[0],"browserView")).getHeight()>context.getResources().getDisplayMetrics().heightPixels*.3,"Ximalaya webpage collapsed");test.runOnMainSync(()->{try{((WebView)FullPortChecks.field(login[0],"browserView")).evaluateJavascript("document.getElementById('complete').click()",null);}catch(Exception e){throw new RuntimeException(e);}});}
            else{helper.await(()->{ImageView qr=(ImageView)FullPortChecks.field(login[0],"loginQr");android.graphics.Rect visible=new android.graphics.Rect();return Math.min(qr.getWidth(),qr.getHeight())>context.getResources().getDisplayMetrics().heightPixels*.5&&qr.getGlobalVisibleRect(visible)&&visible.height()==qr.getHeight();},"native QR too small or clipped");screenshot("bilibili-qr-panel");test.runOnMainSync(()->{try{((ImageView)FullPortChecks.field(login[0],"loginQr")).performClick();}catch(Exception e){throw new RuntimeException(e);}});helper.await(()->FullPortChecks.field(login[0],"qrZoom")!=null,"fullscreen QR not opened");SystemClock.sleep(200);Bitmap screen=test.getUiAutomation().takeScreenshot();try{check(PluginQrImage.payload(screen).equals(server.qr()),"fullscreen QR pixels do not decode to original provider URL");}finally{screen.recycle();}screenshot("bilibili-qr-large");test.runOnMainSync(()->{try{((QrZoom)FullPortChecks.field(login[0],"qrZoom")).close();}catch(Exception e){throw new RuntimeException(e);}});server.confirmed=true;}
            check(finished.await(18,TimeUnit.SECONDS)&&success[0],"provider login not validated: "+raw[0]);check(server.validated,"original account endpoint did not verify candidate cookie");helper.await(()->activity.getResources().getConfiguration().orientation==Configuration.ORIENTATION_LANDSCAPE,"login did not restore landscape");screenshot(ximalaya?"ximalaya-login-return":"landscape-icons");String key=ximalaya?"session":"cookie",saved=context.getSharedPreferences("plugin_data_"+id,0).getString(key,"");check(!saved.isEmpty(),"validated source account missing");
            server.reject=true;server.confirmed=false;CountDownLatch failed=new CountDownLatch(1);manager.export(id,"signIn",new JSONObject(),(ok,value)->{success[0]=ok;failed.countDown();});helper.await(()->{login[0]=runtime(manager,id);return login[0]!=null&&FullPortChecks.field(login[0],ximalaya?"browserView":"loginBitmap")!=null;},"second provider login missing");if(ximalaya){helper.await(()->((WebView)FullPortChecks.field(login[0],"browserView")).getProgress()==100,"Ximalaya retry did not load");test.runOnMainSync(()->{try{((WebView)FullPortChecks.field(login[0],"browserView")).evaluateJavascript("document.getElementById('complete').click()",null);}catch(Exception e){throw new RuntimeException(e);}});}else server.confirmed=true;check(failed.await(18,TimeUnit.SECONDS)&&!success[0],"unverified provider login accepted");check(saved.equals(context.getSharedPreferences("plugin_data_"+id,0).getString(key,"")),"failed login erased previous account");
        }finally{test.runOnMainSync(()->{manager.close();activity.finish();});helper.cleanup(id);context.getSharedPreferences("library",0).edit().remove("plugin_network_"+id).commit();}
    }
    final class Server implements AutoCloseable {
        final ServerSocket socket=new ServerSocket(0);final ExecutorService workers=Executors.newCachedThreadPool();volatile boolean closed,confirmed,reject,validated;
        Server()throws Exception{Thread thread=new Thread(()->{while(!closed)try{Socket client=socket.accept();workers.execute(()->respond(client));}catch(Exception ignored){}});thread.setDaemon(true);thread.start();}
        String base(){return "http://127.0.0.1:"+socket.getLocalPort();}String qr(){return "https://passport.bilibili.com/qrcode/h5/login?oauthKey=fixture-key";}
        void respond(Socket client){try(Socket current=client){current.setSoTimeout(5000);BufferedReader in=new BufferedReader(new InputStreamReader(current.getInputStream(),"UTF-8"));String first=in.readLine(),line;String path=new URI(first.split(" ")[1]).getPath();Map<String,String> headers=new HashMap<>();while((line=in.readLine())!=null&&!line.isEmpty()){int at=line.indexOf(':');if(at>0)headers.put(line.substring(0,at).toLowerCase(Locale.ROOT),line.substring(at+1).trim());}String body,type="application/json",cookie="";
            if(path.equals("/login")){type="text/html";body="<!doctype html><meta name='viewport' content='width=device-width'><h2>Ximalaya login fixture</h2><button id='complete' onclick=\"location.href='/complete'\">Confirm website login</button>";}
            else if(path.equals("/complete")){cookie="Set-Cookie: 1&_token=fixture-token; Path=/; HttpOnly\r\n";type="text/html";body="Login candidate";}
            else if(path.equals("/revision/main/getCurrentUser")){validated=headers.getOrDefault("cookie","").contains("1&_token=fixture-token");body=new JSONObject().put("ret",reject?401:200).put("data",new JSONObject().put("uid",2468).put("nickname","Ximalaya fixture")).toString();}
            else{JSONObject data=new JSONObject();if(path.endsWith("/generate"))data.put("url",qr()).put("qrcode_key","fixture-key");else if(path.endsWith("/poll")){data.put("code",confirmed?0:86101);if(confirmed)data.put("url","https://passport.bilibili.com/login?DedeUserID=2468&SESSDATA=fixture-session&bili_jct=fixture-csrf");}else if(path.endsWith("/spi"))data.put("b_3","fixture-visitor").put("b_4","fixture4");else if(path.endsWith("/nav")){validated=headers.getOrDefault("cookie","").contains("SESSDATA=fixture-session");data.put("isLogin",!reject&&validated).put("mid",2468).put("uname","Bilibili fixture");}body=new JSONObject().put("code",0).put("data",data).toString();}
            byte[] bytes=body.getBytes("UTF-8");OutputStream out=current.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: "+type+"\r\n"+cookie+"Content-Length: "+bytes.length+"\r\nConnection: close\r\n\r\n").getBytes("US-ASCII"));out.write(bytes);out.flush();
        }catch(Exception ignored){}}
        public void close(){closed=true;try{socket.close();}catch(Exception ignored){}workers.shutdownNow();}
    }
}
